"""Source pages 2-21: algebra, geometry, polar form, powers and roots."""
def populate(add,C,M,table):
 add(2,'Complex number(복소수) · 두 실수로 표현하는 하나의 수',[
  C('실수부와 허수부를 구별합니다.',M(r'z=x+iy,\quad i^2=-1,\quad \operatorname{Re}z=x,\quad\operatorname{Im}z=y'), 'x,y는 실수입니다. Imaginary part(허수부)는 iy가 아니라 그 계수 y입니다. 두 복소수가 같다는 것은 두 실수 좌표가 모두 같다는 뜻입니다.',M(r'x+iy=u+iv\iff x=u,\ y=v')),
  C('덧셈은 성분별로 합니다.',M(r'(x_1+iy_1)+(x_2+iy_2)=(x_1+x_2)+i(y_1+y_2)'), '실수끼리, i의 계수끼리 모읍니다. 원본의 i=√−1은 i²=−1인 허수단위를 택한다는 표기입니다. 음수의 제곱근에 실수의 곱셈 법칙을 무조건 적용하지 않습니다.')
 ],[
  C('1 · i는 제곱하면 −1이 되는 새 단위입니다.','실수의 제곱은 음수가 될 수 없어서 x²=−1의 해를 표현할 수 없습니다. 그래서 i²=−1인 imaginary unit(허수단위)를 도입합니다. 복소수 x+iy는 실수 방향 x와 허수 방향 y를 함께 기록합니다.',M(r'i^2=-1,\qquad z=x+iy\longleftrightarrow(x,y)')),
  C('2 · 같은 종류끼리 모으면 됩니다.','Real part(실수부)는 x, imaginary part(허수부)는 y입니다. i를 포함한 항 iy와 허수부 y를 구별합니다. 덧셈은 문자식의 동류항 정리와 같습니다.',M(r'z_1+z_2=x_1+x_2+iy_1+iy_2=(x_1+x_2)+i(y_1+y_2)'), '두 복소수가 같으려면 가로 위치와 세로 위치가 모두 같아야 하므로 실수부·허수부를 따로 비교합니다. 이 방법을 뒤에서 삼각함수 공식과 미분 조건에도 사용합니다.')
 ])
 add(3,'사칙연산 · i²와 켤레를 이용한 나눗셈',[
  C('뺄셈과 곱셈',M(r'z_1-z_2=(x_1-x_2)+i(y_1-y_2)'),M(r'z_1z_2=x_1x_2+ix_1y_2+ix_2y_1+i^2y_1y_2=(x_1x_2-y_1y_2)+i(x_1y_2+x_2y_1)'), '곱셈의 실수부에 −y₁y₂가 생기는 이유는 i²=−1입니다.'),
  C('분모의 켤레를 곱합니다.',M(r'\frac{z_1}{z_2}=\frac{(x_1+iy_1)(x_2-iy_2)}{(x_2+iy_2)(x_2-iy_2)}=\frac{x_1x_2+y_1y_2}{x_2^2+y_2^2}+i\frac{x_2y_1-x_1y_2}{x_2^2+y_2^2}'), 'z₂≠0일 때만 나눕니다. Conjugate(켤레)를 분자·분모에 같이 곱하면 분모가 양의 실수 x₂²+y₂²가 되어 실수부와 허수부를 읽을 수 있습니다.')
 ],[
  C('1 · 괄호 앞 빼기는 안의 두 항에 모두 적용합니다.',M(r'z_1-z_2=x_1+iy_1-(x_2+iy_2)=(x_1-x_2)+i(y_1-y_2)'), '곱셈은 먼저 네 항을 빠짐없이 만들고 마지막에 i²만 −1로 바꿉니다.',M(r'(x_1+iy_1)(x_2+iy_2)=x_1x_2+ix_1y_2+ix_2y_1-y_1y_2')),
  C('2 · 왜 분모의 허수 부호만 뒤집나요?','(a+b)(a−b)=a²−b²를 쓰면 가운데 항이 없어집니다. b=iy₂이면 b²=−y₂²라서 분모에는 두 제곱의 합이 남습니다.',M(r'(x_2+iy_2)(x_2-iy_2)=x_2^2-(iy_2)^2=x_2^2+y_2^2'), '분모만 바꾸면 값이 달라지므로 같은 conjugate(켤레) x₂−iy₂를 분자에도 곱합니다.',M(r'\frac{z_1}{z_2}=\frac{(x_1x_2+y_1y_2)+i(x_2y_1-x_1y_2)}{x_2^2+y_2^2}'), '분자가 a+ib, 분모가 실수 d이면 a/d+i(b/d)로 나눌 수 있습니다. z₂=0이면 분모도 0이므로 이 계산을 하지 않습니다.')
 ])
 add(4,'원본 예제 · 8+3i와 9−2i의 사칙연산',[
  C('합과 차',M(r'z_1+z_2=(8+9)+i(3-2)=17+i'),M(r'z_1-z_2=(8+3i)-(9-2i)=(8-9)+i(3+2)=-1+5i')),
  C('곱과 몫',M(r'(8+3i)(9-2i)=72-16i+27i-6i^2=78+11i'),M(r'\frac{8+3i}{9-2i}=\frac{(8+3i)(9+2i)}{81+4}=\frac{72+43i+6i^2}{85}=\frac{66}{85}+i\frac{43}{85}'), '몫에 9−2i를 다시 곱하면 8+3i가 되는지 확인할 수 있습니다. 원본 최종 결과 네 개는 맞습니다.')
 ],[
  C('1 · 덧셈·뺄셈은 괄호를 풀고 정리합니다.',M(r'(8+3i)+(9-2i)=8+9+(3-2)i=17+i'),M(r'(8+3i)-(9-2i)=8+3i-9+2i=-1+5i'), '빼는 수의 허수부가 −2이므로 3−(−2)=5입니다. 빼기의 빼기를 놓치면 결과가 달라집니다.'),
  C('2 · 곱셈의 네 항을 하나씩 만듭니다.',M(r'8\cdot9+8(-2i)+(3i)9+(3i)(-2i)=72-16i+27i-6i^2'),M(r'72+6+(-16+27)i=78+11i'), '마지막 항은 −6×(−1)=+6입니다. 실수 항과 허수 항을 분리해서 더합니다.'),
  C('3 · 나눗셈은 켤레로 분모를 실수로 만듭니다.',M(r'\frac{8+3i}{9-2i}\cdot\frac{9+2i}{9+2i}=\frac{72+16i+27i+6i^2}{81-4i^2}'),M(r'=\frac{66+43i}{85}=\frac{66}{85}+\frac{43}{85}i'), '분자의 +6i²는 −6, 분모의 −4i²는 +4입니다. Conjugate(켤레)를 곱한 뒤에도 두 위치의 부호를 각각 확인합니다.'),
  C('4 · 나눗셈을 거꾸로 검산합니다.',M(r'\frac{(66+43i)(9-2i)}{85}=\frac{594+86+i(-132+387)}{85}=8+3i'), '곱해서 원래 분자로 돌아오므로 몫이 맞습니다. 계산 예제는 결과만 보고 넘어가기보다 이 역연산으로 부호를 확인할 수 있습니다.')
 ],role='원본 예제 · 상세 풀이')
 add(5,'Algebraic laws(대수 법칙) · 덧셈의 항등원과 역원',[
  C('교환·결합 법칙',M(r'z_1+z_2=z_2+z_1,\quad z_1+(z_2+z_3)=(z_1+z_2)+z_3'),M(r'z_1z_2=z_2z_1,\quad z_1(z_2z_3)=(z_1z_2)z_3'), 'Commutative law(교환법칙)는 순서, associative law(결합법칙)는 묶는 방식에 관한 성질입니다. 곱셈도 성립하지만 뺄셈·나눗셈까지 같은 법칙으로 확대하지 않습니다.'),
  C('덧셈을 바꾸지 않는 수와 취소하는 수',M(r'z+0=z,\qquad z+(-z)=0,\qquad -z=-x-iy'), 'Additive identity(덧셈 항등원)는 0, additive inverse(덧셈 역원)는 −z입니다. 원본 δ는 이 역원을 가리키므로 δ=−z입니다.')
 ],[
  C('1 · 법칙 이름은 어떤 조작을 허용하는지 알려 줍니다.','Commutative(교환 가능)는 두 수의 자리를 바꿔도 같다는 뜻이고, associative(결합 가능)는 세 수의 괄호 위치를 바꿔도 같다는 뜻입니다.',M(r'z_1+z_2=z_2+z_1,\qquad(z_1z_2)z_3=z_1(z_2z_3)'), '이는 계산 순서를 편하게 바꿀 근거입니다. 복소수라고 실수의 대수 규칙을 전부 새로 만들 필요는 없습니다.'),
  C('2 · “그대로 두기”와 “없애기”를 구별합니다.',M(r'(x+iy)+0=x+iy,\qquad (x+iy)+(-x-iy)=0'), 'Identity(항등원)는 더해도 원래 수를 유지하는 0입니다. Inverse(역원)는 그 수와 더해 0을 만드는 −z입니다. 실수부와 허수부를 둘 다 반대로 해야 하므로 켤레 x−iy와는 다릅니다.')
 ])
 add(6,'곱셈의 항등원·역원과 분배법칙',[
  C('곱셈의 역원은 0이 아닌 수에만 있습니다.',M(r'z\cdot1=z,\qquad z^{-1}=\frac1z=\frac{\bar z}{|z|^2}=\frac{x-iy}{x^2+y^2}\quad(z\ne0)'), 'Multiplicative identity(곱셈 항등원)는 1입니다. 곱해서 1을 만드는 multiplicative inverse(곱셈 역원)는 1/z입니다. 0에는 역원이 없습니다.'),
  C('분배법칙으로 괄호를 펼칩니다.',M(r'z_1(z_2+z_3)=z_1z_2+z_1z_3'), 'Distributive law(분배법칙)는 덧셈과 곱셈을 연결합니다. 복소수 다항식 전개와 미분의 계산에서 그대로 사용합니다.')
 ],[
  C('1 · 더해서 0과 곱해서 1은 다른 목표입니다.','Additive inverse(덧셈 역원)는 −z였지만 multiplicative inverse(곱셈 역원)는 1/z입니다. z(x−iy)=x²+y²이므로 곱을 1로 만들려면 이 실수로 나눕니다.',M(r'z\frac{x-iy}{x^2+y^2}=1,\qquad z^{-1}=\frac{x-iy}{x^2+y^2}'), 'x=y=0이면 분모가 0입니다. 0에 어떤 복소수를 곱해도 1이 되지 않으므로 역원이 없습니다.'),
  C('2 · 큰 괄호를 작은 곱으로 나눕니다.',M(r'z_1(z_2+z_3)=z_1z_2+z_1z_3'), 'Distributive law(분배법칙)는 괄호 안의 각 항에 바깥 수를 한 번씩 곱하는 규칙입니다. 앞의 네 항 곱셈과 뒤의 (z+Δz)³ 전개가 이 규칙에 기반합니다.')
 ])
 add(7,'Complex conjugate(켤레복소수) · 실수부와 허수부 추출',[
  C('켤레는 허수부의 부호를 바꿉니다.',M(r'\bar z=x-iy,\quad z+\bar z=2x,\quad z-\bar z=2iy'),M(r'\operatorname{Re}z=\frac{z+\bar z}{2},\qquad\operatorname{Im}z=\frac{z-\bar z}{2i}'), '허수부를 구하는 식에는 2뿐 아니라 i도 나눕니다. 결과 Im z는 실수 y입니다.'),
  C('연산과 켤레의 관계',M(r'\overline{z_1\pm z_2}=\bar z_1\pm\bar z_2,\quad\overline{z_1z_2}=\bar z_1\bar z_2,\quad\overline{z_1/z_2}=\bar z_1/\bar z_2\quad(z_2\ne0)'), '전개식의 i를 −i로 바꾸어 확인할 수 있습니다. 켤레를 두 번 취하면 원래 수로 돌아옵니다.')
 ],[
  C('1 · 더하면 허수 항이, 빼면 실수 항이 사라집니다.',M(r'(x+iy)+(x-iy)=2x,\qquad(x+iy)-(x-iy)=2iy'), 'Complex conjugate(켤레복소수)는 실수부를 유지하고 허수부 부호만 뒤집은 수입니다. 두 수를 더하거나 빼면 원하는 성분만 따로 남길 수 있습니다.',M(r'x=\frac{z+\bar z}{2},\qquad y=\frac{z-\bar z}{2i}')),
  C('2 · 긴 식에서도 i의 부호를 일관되게 뒤집습니다.','합·차·곱·몫 전체에 켤레를 취하는 것은 각 수의 켤레를 같은 방식으로 계산하는 것과 같습니다. 나눗셈에서는 분모가 0이 아닌 조건이 필요합니다.',M(r'\overline{z_1z_2}=\bar z_1\bar z_2,\qquad\overline{\bar z}=z'), '켤레는 −z가 아닙니다. −z는 x,y를 모두 뒤집고, 켤레는 y만 뒤집습니다. 다음의 평면 그림에서 차이를 확인합니다.')
 ])
 add(8,'Complex plane(복소평면) · 벡터로 보는 합과 차',[
  C('복소수 한 개는 평면의 점 한 개입니다.','Real axis(실수축)를 가로, imaginary axis(허수축)를 세로로 잡습니다. z=x+iy는 점 (x,y) 또는 원점에서 그 점으로 향하는 위치벡터입니다.',M(r'z_1+z_2\leftrightarrow(x_1+x_2,y_1+y_2)')),
  C('평행사변형과 변위',M(r'z_1-z_2\leftrightarrow(x_1-x_2,y_1-y_2)'), 'Parallelogram law(평행사변형 법칙)로 두 위치벡터의 합을 그립니다. 차 z₁−z₂는 z₂에서 z₁으로 향하는 변위를 원점으로 옮겨 놓은 벡터입니다. 복소수 곱셈은 성분별 곱이나 내적과 다르며 뒤에서 회전·확대로 해석합니다.')
 ],[
  C('1 · 수직선에 세로축을 하나 추가합니다.','실수만 쓰면 수직선 위 한 좌표로 충분합니다. 복소수에는 x와 y 두 숫자가 있으므로 가로·세로 두 축이 필요합니다. 원본의 3+i는 오른쪽 3, 위쪽 1인 점입니다.'),
  C('2 · 더하기는 두 번 이동하기입니다.','먼저 z₁만큼 이동하고, 그 끝에서 z₂만큼 다시 이동합니다. 최종 위치가 z₁+z₂입니다. 이동 순서를 바꿔도 끝점이 같아 덧셈 교환법칙을 그림으로 이해할 수 있습니다.',M(r'(x_1,y_1)+(x_2,y_2)=(x_1+x_2,y_1+y_2)')),
  C('3 · 빼기는 두 점 사이의 차이입니다.',M(r'z_2+(z_1-z_2)=z_1'), '이 식을 보면 z₂에서 출발해 z₁−z₂만큼 가면 z₁에 도착합니다. 따라서 z₁−z₂의 방향은 두 번째 점에서 첫 번째 점으로 향합니다. 그림의 화살표를 반대로 읽지 않습니다.')
 ])
 add(9,'Modulus(절댓값) · 거리와 켤레의 관계',[
  C('절댓값은 원점으로부터의 거리입니다.',M(r'|z|=\sqrt{x^2+y^2}\ge0,\quad |\operatorname{Re}z|\le|z|,\quad |\operatorname{Im}z|\le|z|'), 'Pythagorean theorem(피타고라스 정리)을 적용했습니다. |z|는 실수이며 z와 다릅니다. 일반 복소수에 실수와 같은 대소순서를 붙이는 것은 아닙니다.'),
  C('켤레는 실수축 반사, −z는 원점 대칭',M(r'z\bar z=(x+iy)(x-iy)=x^2+y^2=|z|^2,\qquad|\bar z|=|z|'), '반사는 거리를 바꾸지 않습니다. z≠0에서 1/z=bar z/|z|²라는 나눗셈 공식의 기하적 근거이기도 합니다.')
 ],[
  C('1 · 복소수의 크기는 두 좌표를 합한 값이 아닙니다.','점 (x,y)까지의 거리는 직각삼각형 빗변입니다. 그래서 x²+y²를 구한 뒤 양의 제곱근을 취합니다.',M(r'|x+iy|=\sqrt{x^2+y^2}'), '가로 길이 |x|와 세로 길이 |y|는 빗변보다 길 수 없어 둘 다 |z| 이하입니다. 크기 |z|에는 i가 남지 않습니다.'),
  C('2 · 거울에 비춰도 중심까지 거리는 같습니다.','Conjugate(켤레) x−iy는 점을 실수축 위아래로 뒤집습니다. 반면 −x−iy는 원점을 중심으로 반 바퀴 돌립니다.',M(r'z\bar z=x^2-(iy)^2=x^2+y^2=|z|^2'), '복소수와 켤레의 곱이 거리의 제곱이 되므로 분모를 실수로 만들 때 켤레를 사용했던 것입니다.')
 ])
 add(10,'Triangle inequality(삼각부등식) · 증명',[
  C('직선 이동은 두 번 나누어 이동한 길이보다 길지 않습니다.',M(r'|z_1+z_2|\le|z_1|+|z_2|'), '왼쪽은 합 벡터의 길이, 오른쪽은 두 벡터 길이의 합입니다. 제곱하면 켤레를 이용해 계산할 수 있습니다.'),
  C('제곱 전개와 실수부의 상한',M(r'|z_1+z_2|^2=|z_1|^2+z_1\bar z_2+\overline{z_1\bar z_2}+|z_2|^2'),M(r'=|z_1|^2+2\operatorname{Re}(z_1\bar z_2)+|z_2|^2\le |z_1|^2+2|z_1||z_2|+|z_2|^2'),M(r'=(|z_1|+|z_2|)^2'), 'Re w≤|w| 및 |z₁bar z₂|=|z₁||z₂|를 사용합니다. 곱의 절댓값 성질은 |z₁z₂|²=(z₁bar z₁)(z₂bar z₂)로 독립 확인할 수 있어 순환 논증이 아닙니다.')
 ],[
  C('1 · 왜 어려운 절댓값을 제곱하나요?','Modulus(절댓값)는 제곱근이라 그대로 더하기 어렵습니다. 제곱하면 |w|²=w bar w로 바뀌어 보통 곱셈을 할 수 있습니다.',M(r'|z_1+z_2|^2=(z_1+z_2)(\bar z_1+\bar z_2)')),
  C('2 · 가운데 두 항은 서로 켤레입니다.',M(r'z_1\bar z_2+z_2\bar z_1=w+\bar w=2\operatorname{Re}w,\quad w=z_1\bar z_2'), '앞 슬라이드의 실수부 추출식을 사용한 것입니다. 어떤 점의 가로 좌표는 전체 거리 이하이므로 Re w≤|w|입니다.',M(r'|z_1+z_2|^2\le |z_1|^2+2|z_1||z_2|+|z_2|^2=(|z_1|+|z_2|)^2')),
  C('3 · 양쪽이 0 이상이므로 제곱근을 취합니다.',M(r'|z_1+z_2|\le |z_1|+|z_2|'), '음수끼리는 제곱 전후 순서가 달라질 수 있지만 지금은 길이라서 0 이상입니다. 이것이 square root(제곱근)를 취해도 부등호 방향을 유지하는 이유입니다.')
 ])
 add(11,'일반화된 삼각부등식·역삼각부등식',[
  C('여러 항과 두 거리의 차',M(r'\left|\sum_{j=1}^n z_j\right|\le\sum_{j=1}^n|z_j|,\qquad\big||z_1|-|z_2|\big|\le|z_1-z_2|'), '앞 식은 두 항 삼각부등식을 반복합니다. 뒤 식은 |z₁|≤|z₁−z₂|+|z₂|와 두 번호를 바꾼 부등식을 결합합니다. 원본의 |z₁−z₂|≥|z₁|−|z₂|도 맞으며 절댓값을 넣은 형태가 더 대칭적입니다.'),
  C('곱과 몫의 크기',M(r'|z_1z_2|=|z_1||z_2|,\qquad\left|\frac{z_1}{z_2}\right|=\frac{|z_1|}{|z_2|}\quad(z_2\ne0)'), '합에는 일반적으로 부등식, 곱·몫에는 등식이 성립합니다. 극한의 오차를 제한할 때 자주 쓰는 도구입니다.')
 ],[
  C('1 · 세 항도 두 항씩 묶으면 됩니다.',M(r'|z_1+z_2+z_3|\le |z_1+z_2|+|z_3|\le |z_1|+|z_2|+|z_3|'), '같은 과정을 반복하면 n항의 generalized triangle inequality(일반화 삼각부등식)를 얻습니다.'),
  C('2 · 두 길이의 차이는 두 점 사이 거리보다 작습니다.',M(r'|z_1|=|(z_1-z_2)+z_2|\le |z_1-z_2|+|z_2|'), '오른쪽의 |z₂|를 빼면 |z₁|−|z₂|≤|z₁−z₂|입니다. 어느 길이가 큰지 몰라도 되도록 두 번호를 바꾼 경우까지 묶습니다.',M(r'\big||z_1|-|z_2|\big|\le |z_1-z_2|')),
  C('3 · 곱하면 길이도 곱해집니다.',M(r'|z_1z_2|^2=z_1z_2\bar z_1\bar z_2=|z_1|^2|z_2|^2'), '모든 크기가 0 이상이라 제곱근을 취하면 |z₁z₂|=|z₁||z₂|입니다. 나눗셈도 분모가 0이 아닐 때 크기를 나누면 됩니다.')
 ])
 add(12,'Polar form(극형식) · 편각과 주값',[
  C('좌표 대신 거리와 방향을 사용합니다.',M(r'z=r(\cos\theta+i\sin\theta),\quad r=|z|,\quad x=r\cos\theta,\ y=r\sin\theta'), 'z≠0에서 argument(편각)는 2π의 정수배만큼 여러 값이 있습니다. 이 자료의 principal argument(편각의 주값)는 −π<Arg z≤π입니다.',M(r'\arg z=\operatorname{Arg}z+2\pi k,\quad k\in\mathbb Z')),
  C('사분면을 확인합니다.','tanθ=y/x만으로는 반대 방향을 구별하지 못합니다. atan2(y,x) 또는 좌표 부호와 기준각으로 편각을 정합니다. x=0에서는 y/x를 쓸 수 없고, z=0의 편각은 정의하지 않습니다. Arg 범위에 맞추는 마지막 단계까지가 주값 계산입니다.')
 ],[
  C('1 · “어디에 있나”를 두 방식으로 말합니다.','직교형식 x+iy는 오른쪽·위쪽으로 간 양이고, polar form(극형식)은 얼마나 멀리 어느 방향으로 갔는지입니다. 반지름 r인 원에서 가로·세로 성분은 rcosθ,rsinθ입니다.',M(r'r=\sqrt{x^2+y^2},\qquad z=r(\cos\theta+i\sin\theta)')),
  C('2 · 한 바퀴 돌아도 같은 점입니다.',M(r'\cos(\theta+2\pi k)=\cos\theta,\quad\sin(\theta+2\pi k)=\sin\theta'), '편각은 하나가 아니라 θ+2πk입니다. 대표 하나를 고르는 규칙이 principal value(주값)이며 이번에는 −π는 빼고 π는 포함합니다. 0은 방향이 없는 원점이라 편각을 정하지 않습니다.'),
  C('3 · 계산기의 arctan 결과를 바로 답으로 쓰지 않습니다.','분수 y/x는 x,y가 모두 음수여도 양수입니다. 그래서 제1사분면과 제3사분면을 혼동할 수 있습니다. 기준각을 구한 뒤 원래 x,y의 부호로 방향을 확인하십시오. 마지막에 2π를 더하거나 빼 주값 범위로 옮깁니다.')
 ])
 add(13,'원본 예제 · √3+i와 −√3−i의 극형식',[
  C('첫 번째 수는 제1사분면',M(r'|\sqrt3+i|=\sqrt{3+1}=2,\quad\theta_1=\pi/6'),M(r'z_1=2e^{i\pi/6},\quad\arg z_1=\pi/6+2\pi k'), '원본의 숫자는 3이 아니라 √3입니다. cos(π/6)=√3/2,sin(π/6)=1/2를 대입해 확인합니다.'),
  C('두 번째 수는 제3사분면',M(r'z_2=2e^{i7\pi/6}=2e^{-i5\pi/6},\quad\operatorname{Arg}z_2=-5\pi/6'), '7π/6은 유효한 편각이지만 주값은 아닙니다. arctan(1/√3)=π/6만 쓰면 반대편 점을 얻습니다. 두 수는 서로 음수이므로 편각이 π만큼 차이 납니다.')
 ],[
  C('1 · √3을 제곱하면 3입니다.',M(r'r=\sqrt{(\sqrt3)^2+1^2}=2'), '가로 성분을 거리로 나누면 √3/2, 세로 성분을 거리로 나누면 1/2입니다. 이 코사인·사인 조합은 30도, 즉 π/6입니다.',M(r'\sqrt3+i=2\left(\cos\frac\pi6+i\sin\frac\pi6\right)')),
  C('2 · 두 좌표가 모두 음수면 반 바퀴 더 갑니다.','−√3−i는 왼쪽 아래에 있으므로 양의 기준각 π/6에 π를 더해 7π/6입니다. 다만 principal argument(편각의 주값) 범위는 π 이하입니다.',M(r'\frac{7\pi}{6}-2\pi=-\frac{5\pi}{6}'),M(r'-\sqrt3-i=2\left(\cos\frac{7\pi}{6}+i\sin\frac{7\pi}{6}\right)=2e^{-i5\pi/6}'), '두 표현은 같은 점을 나타냅니다. 원본 7π/6 자체를 틀렸다고 고치지 않고, 편각과 주값을 구별합니다.')
 ],role='원본 예제 · 상세 풀이')
 add(14,'극형식의 곱셈 · 크기는 곱하고 각은 더합니다.',[
  C('삼각함수 덧셈정리로 묶습니다.',M(r'z_1z_2=r_1r_2[(\cos\theta_1\cos\theta_2-\sin\theta_1\sin\theta_2)+i(\sin\theta_1\cos\theta_2+\cos\theta_1\sin\theta_2)]'),M(r'=r_1r_2[\cos(\theta_1+\theta_2)+i\sin(\theta_1+\theta_2)]')),
  C('확대와 회전',M(r'|z_1z_2|=r_1r_2,\quad\arg(z_1z_2)=\theta_1+\theta_2\pmod{2\pi}'), '고정된 z₂를 곱하는 것은 |z₂|배 확대와 arg z₂만큼 회전을 동시에 수행합니다. 편각 주값들의 합이 항상 곱의 주값인 것은 아니므로 범위를 다시 맞춥니다.')
 ],[
  C('1 · 네 항을 펼친 뒤 i²=−1을 적용합니다.','실수 부분에는 cosθ₁cosθ₂−sinθ₁sinθ₂가, 허수부의 계수에는 sinθ₁cosθ₂+cosθ₁sinθ₂가 남습니다. 이 두 조합은 삼각함수 덧셈정리 그대로입니다.',M(r'\cos(A+B)=\cos A\cos B-\sin A\sin B'),M(r'\sin(A+B)=\sin A\cos B+\cos A\sin B')),
  C('2 · 긴 전개를 거리와 방향으로 읽습니다.',M(r'z_1z_2=r_1r_2\{\cos(\theta_1+\theta_2)+i\sin(\theta_1+\theta_2)\}'), '새 거리는 r₁r₂이고 새 방향은 θ₁+θ₂입니다. 즉 복소수 곱셈은 평면에서 rotation(회전)과 scaling(확대·축소)입니다. 합친 각이 주값 범위를 벗어나면 2π를 더하거나 빼서 같은 방향의 대표를 선택합니다.')
 ])
 add(15,'극형식의 나눗셈 · 원본 곱셈 예제',[
  C('나눗셈은 크기의 비와 각의 차',M(r'\frac{z_1}{z_2}=\frac{r_1}{r_2}[\cos(\theta_1-\theta_2)+i\sin(\theta_1-\theta_2)],\qquad z_2\ne0')),
  C('원본 z₁=−2+2i,z₂=3i',M(r'z_1=2\sqrt2e^{i3\pi/4},\quad z_2=3e^{i\pi/2},\quad z_1z_2=6\sqrt2e^{i5\pi/4}=-6-6i'), '곱의 크기는 6√2이고 5π/4는 편각 하나입니다. 주값은 −3π/4입니다. 편집자 연결 계산으로 몫도 같은 규칙을 확인하면 (−2+2i)/(3i)=2/3+(2/3)i이며 편각 π/4입니다.',M(r'\frac{z_1}{z_2}=\frac{2\sqrt2}{3}e^{i\pi/4}=\frac23+\frac23i'))
 ],[
  C('1 · 곱셈을 되돌리면 크기는 나누고 각은 뺍니다.',M(r'\frac{r_1e^{i\theta_1}}{r_2e^{i\theta_2}}=\frac{r_1}{r_2}e^{i(\theta_1-\theta_2)}'), 'r₂=0이면 나눌 수 없습니다. 나머지는 거리의 확대를 되돌리고 회전도 반대로 돌린다는 뜻입니다.'),
  C('2 · 원본의 두 수를 먼저 극형식으로 바꿉니다.','−2+2i는 제2사분면의 135도 방향이고 거리는 √(4+4)=2√2입니다. 3i는 위쪽 90도 방향이고 거리는 3입니다.',M(r'z_1z_2=(2\sqrt2\cdot3)e^{i(3\pi/4+\pi/2)}=6\sqrt2e^{i5\pi/4}'),M(r'6\sqrt2\left(-\frac{\sqrt2}{2}-i\frac{\sqrt2}{2}\right)=-6-6i'), '5π/4는 225도이며 principal argument(편각의 주값)는 −135도, 즉 −3π/4입니다. 직접 (−2+2i)3i=−6i+6i²로 계산해도 같습니다.'),
  C('3 · 같은 데이터로 몫의 규칙도 연결합니다.','편집자 보강으로 원본의 두 수를 나누면 각도는 3π/4−π/2=π/4입니다.',M(r'\frac{z_1}{z_2}=\frac{2\sqrt2}{3}\left(\frac{\sqrt2}{2}+i\frac{\sqrt2}{2}\right)=\frac23+\frac23i'), '이는 별도 문제의 추가가 아니라 바로 위 나눗셈 공식을 같은 원본 수에 적용한 계산입니다.')
 ],role='개념·원본 예제')
 add(16,'Euler’s formula(오일러 공식) · 회전의 지수 표기',[
  C('복소지수로 극형식을 압축합니다.',M(r'e^{i\theta}=\cos\theta+i\sin\theta,\quad |e^{i\theta}|=1,\quad z=re^{i\theta}'), 'θ는 실수입니다. eⁱθ는 양의 실수 지수의 증가·감소가 아니라 단위원 위의 점을 나타냅니다. 원본 그림에서 eⁱ⁰=1,eⁱπ⁄²=i,eⁱπ=−1입니다.'),
  C('곱셈의 각도 덧셈이 지수법칙이 됩니다.',M(r'(r_1e^{i\theta_1})(r_2e^{i\theta_2})=r_1r_2e^{i(\theta_1+\theta_2)}'), '편집자 유도: 지수의 거듭제곱 급수에 iθ를 넣으면 짝수 항은 cosθ, 홀수 항은 i sinθ로 모입니다. 이 단원의 41·47쪽에서 급수 정의를 다시 확인합니다.')
 ],[
  C('1 · 긴 두 삼각함수를 하나의 기호로 묶습니다.',M(r'\cos\theta+i\sin\theta=e^{i\theta}'), 'Euler’s formula(오일러 공식)는 같은 점의 다른 표기입니다. θ가 증가하면 점이 단위원을 반시계방향으로 돕니다. 크기는 √(cos²θ+sin²θ)=1이어서 커지지 않습니다.'),
  C('2 · i를 곱하는 것은 90도 회전입니다.',M(r'e^{i0}=1,\quad e^{i\pi/2}=i,\quad e^{i\pi}=-1,\quad e^{i3\pi/2}=-i'), '두 번 i를 곱하면 180도 회전하여 −1이 됩니다. i²=−1을 그림으로도 이해할 수 있습니다. 일반 복소수는 여기에 거리 r을 곱한 reⁱθ입니다.'),
  C('3 · 왜 거듭제곱 계산이 편해지나요?',M(r'(re^{i\theta})^n=r^ne^{in\theta}'), '같은 수를 n번 곱하면 크기는 n번 곱하고 각은 n번 더합니다. 직교형식의 긴 다항식 전개를 피할 수 있어 마지막 연습문제에서도 사용합니다.')
 ])
 add(17,'역수·켤레·정수 거듭제곱의 기하',[
  C('역수와 켤레는 크기에서 차이가 납니다.',M(r'\frac1z=r^{-1}e^{-i\theta},\qquad\bar z=re^{-i\theta}\quad(z\ne0)'), '둘 다 각도를 반대로 바꾸지만 역수는 반지름도 1/r로 바꿉니다. 원본 그림처럼 |z|<1이면 역수는 단위원 밖, |z|>1이면 안에 있습니다.'),
  C('정수 거듭제곱',M(r'z^n=r^ne^{in\theta},\qquad z^{-n}=r^{-n}e^{-in\theta}=r^{-n}(\cos n\theta-i\sin n\theta)'), '음의 거듭제곱에는 z≠0이 필요합니다. 정수 n에서는 θ에 2πk를 추가해도 결과가 같으므로 값이 하나입니다. 분수 지수의 다가성과 구별합니다.')
 ],[
  C('1 · 켤레와 역수의 방향은 같아도 거리는 다릅니다.',M(r'\bar z=re^{-i\theta},\qquad z^{-1}=\frac1r e^{-i\theta}'), 'Conjugate(켤레)는 실수축에 비추기만 합니다. Reciprocal(역수)는 비춘 뒤 거리를 뒤집습니다. r이 작으면 1/r은 크고, r=1이면 둘이 같습니다.'),
  C('2 · 음의 지수는 먼저 역수라는 뜻입니다.',M(r'z^{-n}=\frac1{z^n}=\frac1{r^n}e^{-in\theta}'), 'cos(−a)=cos a,sin(−a)=−sin a이므로 사인 앞만 음수가 됩니다. 부호를 외우기보다 각도를 반대로 돌렸다고 읽으면 실수를 줄일 수 있습니다. 원점은 역수가 없어서 제외합니다.')
 ])
 add(18,'De Moivre’s formula(드무아브르 공식) · 삼배각 유도',[
  C('정수 거듭제곱과 각의 배수',M(r'(\cos\theta+i\sin\theta)^n=\cos(n\theta)+i\sin(n\theta),\qquad n\in\mathbb Z'), '원본 예제는 n=3을 전개하고 실수부·허수부를 비교합니다.'),
  C('세제곱을 전개합니다.',M(r'(c+is)^3=c^3+3ic^2s-3cs^2-is^3\quad(c=\cos\theta,s=\sin\theta)'),M(r'\cos3\theta=c^3-3cs^2=4c^3-3c,\qquad\sin3\theta=3c^2s-s^3=3s-4s^3'), 's²=1−c² 및 c²=1−s²를 각각 사용합니다. cos³θ는 cosθ의 세제곱이고 cos3θ는 각 3θ의 코사인입니다.')
 ],[
  C('1 · 같은 복소수를 두 가지 방법으로 세제곱합니다.',M(r'(\cos\theta+i\sin\theta)^3=\cos3\theta+i\sin3\theta'), '오른쪽은 polar form(극형식)의 각을 세 배 한 답입니다. 왼쪽은 (a+b)³=a³+3a²b+3ab²+b³로 계산할 수 있습니다.'),
  C('2 · i²=−1과 i³=−i를 각각 넣습니다.',M(r'(c+is)^3=c^3+3c^2(is)+3c(is)^2+(is)^3'),M(r'=(c^3-3cs^2)+i(3c^2s-s^3)'), '같은 복소수는 실수부끼리, 허수부끼리 같아야 합니다. 따라서 첫 괄호가 cos3θ이고 두 번째 괄호가 sin3θ입니다.'),
  C('3 · 피타고라스 항등식으로 한 종류만 남깁니다.',M(r'c^3-3c(1-c^2)=c^3-3c+3c^3=4c^3-3c'),M(r'3(1-s^2)s-s^3=3s-3s^3-s^3=3s-4s^3'), '최종적으로 cos3θ=4cos³θ−3cosθ, sin3θ=3sinθ−4sin³θ입니다. 삼각함수 공식을 따로 외우는 대신 복소수 전개로 다시 만들 수 있습니다.')
 ],role='원본 예제 · 공식 유도')
 add(19,'Nth root(n제곱근) · 크기와 각을 나눕니다.',[
  C('wⁿ=z의 해를 찾습니다.',M(r'z=re^{i\theta}\ne0,\quad w=\rho e^{i\phi},\quad w^n=\rho^ne^{in\phi}=re^{i\theta}'),M(r'\rho^n=r,\qquad n\phi=\theta+2\pi k'), 'n은 양의 정수입니다. 크기는 같은 양수여야 하고 각은 2π의 정수배 차이를 허용합니다. 따라서 ρ=r¹⁄ⁿ,φ=(θ+2πk)/n입니다.'),
  C('한 각만 n으로 나누면 근을 놓칩니다.','각도에 2πk를 더한 뒤 n으로 나누므로 서로 다른 방향 n개가 생깁니다. z=0일 때는 w=0 하나이며, 중복도를 세면 n중근입니다. 다가 기호 z¹⁄ⁿ와 특정 principal root(주근)를 구별합니다.')
 ],[
  C('1 · n번 곱해서 원래 수가 되는 수를 구합니다.','w의 거리가 ρ이고 방향이 φ라면 n번 곱한 wⁿ의 거리는 ρⁿ, 방향은 nφ입니다. 이것이 z의 거리 r과 방향 θ에 맞아야 합니다.',M(r'\rho^n=r\Rightarrow\rho=\sqrt[n]r')),
  C('2 · 각도는 한 바퀴 차이를 허용합니다.',M(r'n\phi=\theta+2\pi k\Rightarrow\phi=\frac{\theta+2\pi k}{n}'), 'θ와 θ+2π는 같은 방향이지만 둘을 n으로 나누면 2π/n만큼 다른 방향이 됩니다. 그래서 복소수의 root(근)가 여러 개 나옵니다. 마지막에 각 근을 n제곱하면 각도 차이가 2πk가 되어 같은 z로 돌아옵니다.')
 ])
 add(20,'n개 근의 공식 · 1의 세제곱근과 네제곱근',[
  C('서로 다른 근은 k=0,…,n−1입니다.',M(r'w_k=r^{1/n}\exp\!\left(i\frac{\theta+2\pi k}{n}\right),\qquad k=0,1,\ldots,n-1'), 'k를 n만큼 늘리면 각이 2π 증가하여 같은 근으로 돌아옵니다. 모든 근은 반지름 r¹⁄ⁿ인 원 위에 등간격으로 놓입니다.'),
  C('원본 unity roots(1의 거듭제곱근)',M(r'w^3=1:\quad1,\ -\frac12+\frac{\sqrt3}{2}i,\ -\frac12-\frac{\sqrt3}{2}i'),M(r'w^4=1:\quad1,i,-1,-i'), 'z=1이면 r=1,θ=0입니다. 세제곱근의 각은 0,2π/3,4π/3, 네제곱근의 각은 0,π/2,π,3π/2입니다.')
 ],[
  C('1 · k를 몇 번 넣어야 하나요?',M(r'\phi_k=\frac\theta n+\frac{2\pi k}{n}'), 'k가 1 증가할 때마다 2π/n만큼 이동합니다. n번 움직이면 한 바퀴여서 처음 근으로 돌아옵니다. 그러므로 0부터 n−1까지만 넣으면 중복 없이 전부 구합니다.'),
  C('2 · 1의 세제곱근을 모두 계산합니다.',M(r'k=0:\ 1,\quad k=1:\cos\frac{2\pi}{3}+i\sin\frac{2\pi}{3}=-\frac12+\frac{\sqrt3}{2}i'),M(r'k=2:\cos\frac{4\pi}{3}+i\sin\frac{4\pi}{3}=-\frac12-\frac{\sqrt3}{2}i'), '거리 1에서 120도씩 나누어 놓은 세 점입니다. 1만 답으로 쓰면 다른 복소근 두 개를 놓칩니다.'),
  C('3 · 네제곱근은 90도 간격입니다.',M(r'e^{i0}=1,\ e^{i\pi/2}=i,\ e^{i\pi}=-1,\ e^{i3\pi/2}=-i'), '네 수를 각각 네제곱하면 모두 1입니다. 원본의 ±1,±i는 이 네 답을 짧게 적은 표현입니다.')
 ])
 add(21,'Roots of unity(1의 거듭제곱근) · 정다각형과 회전',[
  C('한 번 회전하는 수 ω',M(r'\omega=e^{2\pi i/n},\quad \omega^n=1,\quad\{w:w^n=1\}=\{1,\omega,\ldots,\omega^{n-1}\}'), '원본 그림은 n=3,4,5에서 정삼각형·정사각형·정오각형입니다. 여기의 ω는 k=1로 선택하므로 n번이 지나야 처음으로 1에 돌아오는 primitive root(원시근)입니다.'),
  C('하나의 근을 알면 나머지는 회전으로 얻습니다.',M(r'w_1^n=z\ne0\quad\Rightarrow\quad (w_1\omega^k)^n=z,\quad k=0,\ldots,n-1'), 'r¹⁄ⁿ의 크기를 유지하면서 방향만 등간격으로 돌립니다. 앞 Fourier 단원의 DFT(이산 푸리에 변환)에 쓰인 단위원의 등간격 지수와 같은 구조입니다.')
 ],[
  C('1 · ω는 “한 칸 회전”입니다.',M(r'\omega=e^{2\pi i/n}'), 'ω를 한 번 곱하면 각도가 2π/n 증가하고, 두 번 곱하면 두 칸 증가합니다. n번이면 한 바퀴이므로 ωⁿ=1입니다. 원본 세 그림에서 모서리 하나씩 이동한다고 생각하면 됩니다.'),
  C('2 · 원래 근에 한 칸씩 회전을 더합니다.',M(r'(w_1\omega^k)^n=w_1^n\omega^{kn}=z\cdot1=z'), '이미 답 하나 w₁을 알고 있다면 w₁,w₁ω,…,w₁ωⁿ⁻¹을 만들면 됩니다. 왜 모두 답인지 n제곱하여 확인한 식입니다. 이는 모든 nth roots(n제곱근)를 빠뜨리지 않고 구하는 다른 표현입니다.')
 ])
